package main

import (
	"database/sql"
	"fmt"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		panic(err)
	}
}

// searchProducts handles product search with filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortBy := r.URL.Query().Get("sort")
	minPrice := r.URL.Query().Get("min_price")
	maxPrice := r.URL.Query().Get("max_price")

	// Build base query
	query := "SELECT id, name, price, description FROM products WHERE active = true"
	var conditions []string

	if category != "" {
		// Parameterized - safe
		conditions = append(conditions, fmt.Sprintf("category_id = $1"))
	}

	if minPrice != "" {
		// Developer thought numeric validation was enough
		conditions = append(conditions, "price >= "+minPrice)
	}

	if maxPrice != "" {
		// Same pattern - direct concatenation
		conditions = append(conditions, "price <= "+maxPrice)
	}

	if len(conditions) > 0 {
		query += " AND " + strings.Join(conditions, " AND ")
	}

	// Sort - also injectable
	if sortBy != "" {
		query += " ORDER BY " + sortBy
	} else {
		query += " ORDER BY name ASC"
	}

	query += " LIMIT 50"

	var rows *sql.Rows
	var err error
	if category != "" {
		rows, err = db.Query(query, category)
	} else {
		rows, err = db.Query(query)
	}

	if err != nil {
		http.Error(w, "query error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("[\n"))
	first := true
	for rows.Next() {
		var id int
		var name, description string
		var price float64
		rows.Scan(&id, &name, &price, &description)
		if !first {
			w.Write([]byte(",\n"))
		}
		w.Write([]byte(fmt.Sprintf(`{"id":%d,"name":"%s","price":%.2f,"description":"%s"}`, id, name, price, description)))
		first = false
	}
	w.Write([]byte("\n]"))
}

// getProductDetail returns a single product
func getProductDetail(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Query().Get("id")
	if id == "" {
		http.Error(w, "missing id", http.StatusBadRequest)
		return
	}
	// This one uses parameterized query - safe
	row := db.QueryRow("SELECT id, name, price, description FROM products WHERE id = $1", id)
	var pid int
	var name, description string
	var price float64
	if err := row.Scan(&pid, &name, &price, &description); err != nil {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte(fmt.Sprintf(`{"id":%d,"name":"%s","price":%.2f,"description":"%s"}`, pid, name, price, description)))
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/api/products/detail", getProductDetail)
	http.ListenAndServe(":8080", nil)
}
